*** Begin Patch
*** Add File: /workspace/go.mod
+module gron
+
+go 1.21
*** Add File: /workspace/main.go
+package main
+
+import (
+	"bufio"
+	"bytes"
+	"crypto/tls"
+	"encoding/json"
+	"errors"
+	"flag"
+	"fmt"
+	"io"
+	"net/http"
+	neturl "net/url"
+	"os"
+	"sort"
+	"strconv"
+	"strings"
+	"unicode"
+	"unicode/utf8"
+)
+
+const helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable
+
+Usage:
+  gron [OPTIONS] [FILE|URL|-]
+
+Options:
+  -u, --ungron     Reverse the operation (turn assignments back into JSON)
+  -v, --values     Print just the values of provided assignments
+  -c, --colorize   Colorize output (default on tty)
+  -m, --monochrome Monochrome (don't colorize output)
+  -s, --stream     Treat each line of input as a separate JSON object
+  -k, --insecure   Disable certificate validation
+  -x, --proxy      Set proxy configuration
+      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
+  -j, --json       Represent gron data as JSON stream
+      --no-sort    Don't sort output (faster)
+      --version    Print version information
+
+Exit Codes:
+  0	OK
+  1	Failed to open file
+  2	Failed to read input
+  3	Failed to form statements
+  4	Failed to fetch URL
+  5	Failed to parse statements
+  6	Failed to encode JSON
+
+Examples:
+  gron /tmp/apiresponse.json
+  gron http://jsonplaceholder.typicode.com/users/1 
+  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
+  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
+`
+
+const versionText = "gron version dev\n"
+
+type options struct {
+	ungron     bool
+	values     bool
+	colorize   bool
+	monochrome bool
+	stream     bool
+	insecure   bool
+	jsonOutput bool
+	noSort     bool
+	proxy      string
+	noProxy    string
+	version    bool
+	help       bool
+}
+
+type segmentKind int
+
+const (
+	segmentIdentifier segmentKind = iota
+	segmentBracketString
+	segmentIndex
+)
+
+type pathSegment struct {
+	kind  segmentKind
+	key   string
+	index int
+}
+
+type statement struct {
+	path  []pathSegment
+	value any
+}
+
+func main() {
+	os.Exit(run(os.Args[1:]))
+}
+
+func run(args []string) int {
+	opts, inputArg, parseErr := parseArgs(args)
+	if parseErr != nil {
+		printUsage()
+		return 2
+	}
+	if opts.help {
+		printUsage()
+		return 0
+	}
+	if opts.version {
+		_, _ = io.WriteString(os.Stdout, versionText)
+		return 0
+	}
+
+	data, code, err := readInput(inputArg, opts)
+	if err != nil {
+		printErr(err)
+		return code
+	}
+
+	if opts.ungron {
+		if opts.jsonOutput {
+			return runJSONUngron(data)
+		}
+		return runPlainUngron(data)
+	}
+
+	if opts.values {
+		return runValues(data)
+	}
+
+	if opts.stream {
+		return runForwardStream(data, opts)
+	}
+
+	return runForward(data, opts)
+}
+
+func parseArgs(args []string) (options, string, error) {
+	var opts options
+
+	fs := flag.NewFlagSet("gron", flag.ContinueOnError)
+	fs.SetOutput(os.Stderr)
+	fs.Usage = printUsage
+
+	fs.BoolVar(&opts.help, "h", false, "")
+	fs.BoolVar(&opts.help, "help", false, "")
+	fs.BoolVar(&opts.ungron, "u", false, "")
+	fs.BoolVar(&opts.ungron, "ungron", false, "")
+	fs.BoolVar(&opts.values, "v", false, "")
+	fs.BoolVar(&opts.values, "values", false, "")
+	fs.BoolVar(&opts.colorize, "c", false, "")
+	fs.BoolVar(&opts.colorize, "colorize", false, "")
+	fs.BoolVar(&opts.monochrome, "m", false, "")
+	fs.BoolVar(&opts.monochrome, "monochrome", false, "")
+	fs.BoolVar(&opts.stream, "s", false, "")
+	fs.BoolVar(&opts.stream, "stream", false, "")
+	fs.BoolVar(&opts.insecure, "k", false, "")
+	fs.BoolVar(&opts.insecure, "insecure", false, "")
+	fs.StringVar(&opts.proxy, "x", "", "")
+	fs.StringVar(&opts.proxy, "proxy", "", "")
+	fs.StringVar(&opts.noProxy, "noproxy", "", "")
+	fs.BoolVar(&opts.jsonOutput, "j", false, "")
+	fs.BoolVar(&opts.jsonOutput, "json", false, "")
+	fs.BoolVar(&opts.noSort, "no-sort", false, "")
+	fs.BoolVar(&opts.version, "version", false, "")
+
+	if err := fs.Parse(args); err != nil {
+		return options{}, "", err
+	}
+
+	inputArg := ""
+	if fs.NArg() > 0 {
+		inputArg = fs.Arg(0)
+	}
+
+	return opts, inputArg, nil
+}
+
+func printUsage() {
+	_, _ = io.WriteString(os.Stderr, helpText)
+}
+
+func printErr(err error) {
+	_, _ = fmt.Fprintf(os.Stderr, "%v\n", err)
+}
+
+func readInput(inputArg string, opts options) ([]byte, int, error) {
+	if inputArg == "" || inputArg == "-" {
+		data, err := io.ReadAll(os.Stdin)
+		if err != nil {
+			return nil, 2, err
+		}
+		return data, 0, nil
+	}
+
+	if strings.HasPrefix(inputArg, "http://") || strings.HasPrefix(inputArg, "https://") {
+		return fetchURL(inputArg, opts)
+	}
+
+	file, err := os.Open(inputArg)
+	if err != nil {
+		return nil, 1, err
+	}
+	defer file.Close()
+
+	data, err := io.ReadAll(file)
+	if err != nil {
+		return nil, 2, err
+	}
+	return data, 0, nil
+}
+
+func fetchURL(rawURL string, opts options) ([]byte, int, error) {
+	transport := http.DefaultTransport.(*http.Transport).Clone()
+	if opts.insecure {
+		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
+	}
+	if opts.proxy != "" || opts.noProxy != "" {
+		transport.Proxy = buildProxyFunc(opts.proxy, opts.noProxy)
+	}
+
+	client := &http.Client{Transport: transport}
+	resp, err := client.Get(rawURL)
+	if err != nil {
+		return nil, 4, err
+	}
+	defer resp.Body.Close()
+
+	data, err := io.ReadAll(resp.Body)
+	if err != nil {
+		return nil, 4, err
+	}
+	return data, 0, nil
+}
+
+func buildProxyFunc(proxyValue, noProxyValue string) func(*http.Request) (*neturl.URL, error) {
+	var noProxyHosts map[string]struct{}
+	if noProxyValue != "" {
+		noProxyHosts = map[string]struct{}{}
+		for _, host := range strings.Split(noProxyValue, ",") {
+			host = strings.TrimSpace(host)
+			if host != "" {
+				noProxyHosts[host] = struct{}{}
+			}
+		}
+	}
+
+	return func(req *http.Request) (*neturl.URL, error) {
+		if len(noProxyHosts) > 0 {
+			if _, ok := noProxyHosts[req.URL.Host]; ok {
+				return nil, nil
+			}
+		}
+		if proxyValue == "" {
+			return http.ProxyFromEnvironment(req)
+		}
+		return neturl.Parse(proxyValue)
+	}
+}
+
+func runForward(data []byte, opts options) int {
+	value, err := decodeJSON(data)
+	if err != nil {
+		printErr(fmt.Errorf("failed to form statements: %w", err))
+		return 3
+	}
+
+	stmts := collectStatements(value, nil)
+	if !opts.noSort {
+		sortStatements(stmts)
+	}
+
+	if err := writeStatements(os.Stdout, stmts, opts.jsonOutput); err != nil {
+		printErr(fmt.Errorf("failed to encode JSON: %w", err))
+		return 6
+	}
+
+	return 0
+}
+
+func runForwardStream(data []byte, opts options) int {
+	root := statement{
+		path:  nil,
+		value: []any{},
+	}
+	if err := writeStatement(os.Stdout, root, opts.jsonOutput); err != nil {
+		printErr(fmt.Errorf("failed to encode JSON: %w", err))
+		return 6
+	}
+
+	scanner := newScanner(data)
+	for index := 0; scanner.Scan(); index++ {
+		line := bytes.TrimSpace(scanner.Bytes())
+		value, err := decodeJSON(line)
+		if err != nil {
+			printErr(fmt.Errorf("failed to form statements: %w", err))
+			return 3
+		}
+
+		stmts := collectStatements(value, []pathSegment{{kind: segmentIndex, index: index}})
+		if !opts.noSort {
+			sortStatements(stmts)
+		}
+		if err := writeStatements(os.Stdout, stmts, opts.jsonOutput); err != nil {
+			printErr(fmt.Errorf("failed to encode JSON: %w", err))
+			return 6
+		}
+	}
+
+	return 0
+}
+
+func runPlainUngron(data []byte) int {
+	scanner := newScanner(data)
+
+	var merged any
+	parsed := false
+
+	for scanner.Scan() {
+		line := scanner.Text()
+		stmt, ok, err := parsePlainStatementLine(line)
+		if err != nil {
+			printErr(err)
+			return 5
+		}
+		if !ok {
+			continue
+		}
+
+		fragment := buildFragment(stmt.path, stmt.value)
+		if !parsed {
+			merged = fragment
+			parsed = true
+			continue
+		}
+
+		merged, err = mergeValues(merged, fragment)
+		if err != nil {
+			printErr(fmt.Errorf("failed to merge statements: %w", err))
+			return 5
+		}
+	}
+
+	if !parsed {
+		printErr(errors.New("no statements were parsed"))
+		return 5
+	}
+
+	if root, ok := maybeUnwrapJSONRoot(merged); ok {
+		merged = root
+	}
+
+	encoded, err := marshalJSONIndent(merged)
+	if err != nil {
+		printErr(fmt.Errorf("failed to encode JSON: %w", err))
+		return 6
+	}
+
+	_, _ = os.Stdout.Write(encoded)
+	_, _ = os.Stdout.Write([]byte("\n"))
+	return 0
+}
+
+func runJSONUngron(data []byte) int {
+	scanner := newScanner(data)
+
+	var merged any
+	parsed := false
+
+	for scanner.Scan() {
+		line := bytes.TrimSpace(scanner.Bytes())
+		value, err := decodeJSON(line)
+		if err != nil {
+			printErr(err)
+			return 5
+		}
+
+		stmt, err := parseJSONStreamStatement(value)
+		if err != nil {
+			printErr(err)
+			return 5
+		}
+
+		fragment := buildFragment(stmt.path, stmt.value)
+		if !parsed {
+			merged = fragment
+			parsed = true
+			continue
+		}
+
+		merged, err = mergeValues(merged, fragment)
+		if err != nil {
+			printErr(fmt.Errorf("failed to merge statements: %w", err))
+			return 5
+		}
+	}
+
+	if !parsed {
+		printErr(errors.New("no statements were parsed"))
+		return 5
+	}
+
+	encoded, err := marshalJSONIndent(merged)
+	if err != nil {
+		printErr(fmt.Errorf("failed to encode JSON: %w", err))
+		return 6
+	}
+
+	_, _ = os.Stdout.Write(encoded)
+	_, _ = os.Stdout.Write([]byte("\n"))
+	return 0
+}
+
+func runValues(data []byte) int {
+	scanner := newScanner(data)
+
+	for scanner.Scan() {
+		stmt, ok, err := parsePlainStatementLine(scanner.Text())
+		if err != nil || !ok {
+			continue
+		}
+		switch stmt.value.(type) {
+		case map[string]any, []any:
+			continue
+		}
+
+		encoded, encodeErr := marshalJSON(stmt.value)
+		if encodeErr != nil {
+			continue
+		}
+		_, _ = os.Stdout.Write(encoded)
+		_, _ = os.Stdout.Write([]byte("\n"))
+	}
+
+	return 0
+}
+
+func decodeJSON(data []byte) (any, error) {
+	decoder := json.NewDecoder(bytes.NewReader(data))
+	decoder.UseNumber()
+
+	var value any
+	if err := decoder.Decode(&value); err != nil {
+		return nil, err
+	}
+
+	var extra any
+	if err := decoder.Decode(&extra); err != io.EOF {
+		if err == nil {
+			return nil, errors.New("invalid JSON input")
+		}
+		return nil, err
+	}
+
+	return value, nil
+}
+
+func collectStatements(value any, base []pathSegment) []statement {
+	var stmts []statement
+	collectStatementsInto(&stmts, value, base)
+	return stmts
+}
+
+func collectStatementsInto(out *[]statement, value any, base []pathSegment) {
+	*out = append(*out, statement{
+		path:  copyPath(base),
+		value: statementValue(value),
+	})
+
+	switch typed := value.(type) {
+	case map[string]any:
+		for key, child := range typed {
+			kind := segmentBracketString
+			if isIdentifier(key) {
+				kind = segmentIdentifier
+			}
+			next := appendPath(base, pathSegment{
+				kind: kind,
+				key:  key,
+			})
+			collectStatementsInto(out, child, next)
+		}
+	case []any:
+		for index, child := range typed {
+			next := appendPath(base, pathSegment{
+				kind:  segmentIndex,
+				index: index,
+			})
+			collectStatementsInto(out, child, next)
+		}
+	}
+}
+
+func statementValue(value any) any {
+	switch value.(type) {
+	case map[string]any:
+		return map[string]any{}
+	case []any:
+		return []any{}
+	default:
+		return value
+	}
+}
+
+func writeStatements(w io.Writer, stmts []statement, jsonOutput bool) error {
+	for _, stmt := range stmts {
+		if err := writeStatement(w, stmt, jsonOutput); err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+func writeStatement(w io.Writer, stmt statement, jsonOutput bool) error {
+	var line []byte
+	var err error
+
+	if jsonOutput {
+		line, err = renderJSONStatement(stmt)
+	} else {
+		line, err = renderPlainStatement(stmt)
+	}
+	if err != nil {
+		return err
+	}
+
+	_, err = w.Write(line)
+	return err
+}
+
+func renderPlainStatement(stmt statement) ([]byte, error) {
+	value, err := marshalJSON(stmt.value)
+	if err != nil {
+		return nil, err
+	}
+
+	var path strings.Builder
+	path.WriteString("json")
+	for _, seg := range stmt.path {
+		switch seg.kind {
+		case segmentIdentifier:
+			path.WriteByte('.')
+			path.WriteString(seg.key)
+		case segmentBracketString:
+			path.WriteByte('[')
+			key, keyErr := marshalJSON(seg.key)
+			if keyErr != nil {
+				return nil, keyErr
+			}
+			path.Write(key)
+			path.WriteByte(']')
+		case segmentIndex:
+			path.WriteByte('[')
+			path.WriteString(strconv.Itoa(seg.index))
+			path.WriteByte(']')
+		}
+	}
+
+	var line bytes.Buffer
+	line.WriteString(path.String())
+	line.WriteString(" = ")
+	line.Write(value)
+	line.WriteString(";\n")
+	return line.Bytes(), nil
+}
+
+func renderJSONStatement(stmt statement) ([]byte, error) {
+	path := make([]any, 0, len(stmt.path))
+	for _, seg := range stmt.path {
+		if seg.kind == segmentIndex {
+			path = append(path, seg.index)
+			continue
+		}
+		path = append(path, seg.key)
+	}
+
+	pair := []any{path, stmt.value}
+	encoded, err := marshalJSON(pair)
+	if err != nil {
+		return nil, err
+	}
+
+	return append(encoded, '\n'), nil
+}
+
+func sortStatements(stmts []statement) {
+	sort.Slice(stmts, func(i, j int) bool {
+		return comparePaths(stmts[i].path, stmts[j].path) < 0
+	})
+}
+
+func comparePaths(left, right []pathSegment) int {
+	limit := len(left)
+	if len(right) < limit {
+		limit = len(right)
+	}
+
+	for i := 0; i < limit; i++ {
+		if diff := compareSegment(left[i], right[i]); diff != 0 {
+			return diff
+		}
+	}
+
+	switch {
+	case len(left) < len(right):
+		return -1
+	case len(left) > len(right):
+		return 1
+	default:
+		return 0
+	}
+}
+
+func compareSegment(left, right pathSegment) int {
+	if left.kind != right.kind {
+		return compareInts(segmentRank(left.kind), segmentRank(right.kind))
+	}
+
+	if left.kind == segmentIndex {
+		return compareInts(left.index, right.index)
+	}
+
+	return strings.Compare(left.key, right.key)
+}
+
+func segmentRank(kind segmentKind) int {
+	switch kind {
+	case segmentIdentifier:
+		return 0
+	case segmentBracketString:
+		return 1
+	default:
+		return 2
+	}
+}
+
+func parsePlainStatementLine(line string) (statement, bool, error) {
+	var stmt statement
+
+	trimmed := strings.TrimSpace(line)
+	if trimmed == "" {
+		return stmt, false, nil
+	}
+
+	semi := strings.Index(trimmed, ";")
+	if semi < 0 {
+		return stmt, false, fmt.Errorf("ungron failed for `%s`: statement has no value", trimmed)
+	}
+
+	display := strings.TrimSpace(trimmed[:semi+1])
+	core := strings.TrimSpace(display[:len(display)-1])
+	if core == "" {
+		return stmt, false, fmt.Errorf("ungron failed for `%s`: invalid statement", display)
+	}
+
+	path, consumed, err := parsePath(core)
+	if err != nil {
+		return stmt, false, fmt.Errorf("ungron failed for `%s`: invalid statement", display)
+	}
+
+	rest := strings.TrimSpace(core[consumed:])
+	if rest == "" || rest[0] != '=' {
+		return stmt, false, fmt.Errorf("ungron failed for `%s`: invalid statement", display)
+	}
+
+	valueText := strings.TrimSpace(rest[1:])
+	value, err := parsePlainValue(valueText)
+	if err != nil {
+		return stmt, false, fmt.Errorf("ungron failed for `%s`: %w", display, err)
+	}
+
+	stmt = statement{
+		path:  path,
+		value: value,
+	}
+	return stmt, true, nil
+}
+
+func parsePlainValue(valueText string) (any, error) {
+	switch valueText {
+	case "":
+		return nil, fmt.Errorf("invalid value ``")
+	case "{}":
+		return map[string]any{}, nil
+	case "[]":
+		return []any{}, nil
+	}
+
+	value, err := decodeJSON([]byte(valueText))
+	if err != nil {
+		return nil, fmt.Errorf("invalid value `%s`", valueText)
+	}
+
+	switch value.(type) {
+	case map[string]any, []any:
+		return nil, fmt.Errorf("invalid value `%s`", valueText)
+	default:
+		return value, nil
+	}
+}
+
+func parsePath(expr string) ([]pathSegment, int, error) {
+	root, consumed := parseIdentifier(expr)
+	if consumed == 0 {
+		return nil, 0, errors.New("invalid path")
+	}
+
+	path := []pathSegment{{
+		kind: segmentIdentifier,
+		key:  root,
+	}}
+
+	offset := consumed
+	for offset < len(expr) {
+		switch expr[offset] {
+		case '.':
+			name, width := parseIdentifier(expr[offset+1:])
+			if width == 0 {
+				return nil, 0, errors.New("invalid path")
+			}
+			path = append(path, pathSegment{
+				kind: segmentIdentifier,
+				key:  name,
+			})
+			offset += 1 + width
+		case '[':
+			if offset+1 >= len(expr) {
+				return nil, 0, errors.New("invalid path")
+			}
+
+			if expr[offset+1] == '"' {
+				key, width, err := parseJSONString(expr[offset+1:])
+				if err != nil {
+					return nil, 0, err
+				}
+				offset += 1 + width
+				if offset >= len(expr) || expr[offset] != ']' {
+					return nil, 0, errors.New("invalid path")
+				}
+				path = append(path, pathSegment{
+					kind: segmentBracketString,
+					key:  key,
+				})
+				offset++
+				continue
+			}
+
+			end := offset + 1
+			if end >= len(expr) || expr[end] < '0' || expr[end] > '9' {
+				return nil, 0, errors.New("invalid path")
+			}
+			for end < len(expr) && expr[end] >= '0' && expr[end] <= '9' {
+				end++
+			}
+			if end >= len(expr) || expr[end] != ']' {
+				return nil, 0, errors.New("invalid path")
+			}
+
+			index, err := strconv.Atoi(expr[offset+1 : end])
+			if err != nil {
+				return nil, 0, err
+			}
+			path = append(path, pathSegment{
+				kind:  segmentIndex,
+				index: index,
+			})
+			offset = end + 1
+		default:
+			return path, offset, nil
+		}
+	}
+
+	return path, offset, nil
+}
+
+func parseIdentifier(input string) (string, int) {
+	if input == "" {
+		return "", 0
+	}
+
+	var size int
+	for index, r := range input {
+		if index == 0 {
+			if !isIdentifierStart(r) {
+				return "", 0
+			}
+		} else if !isIdentifierContinue(r) {
+			return input[:index], index
+		}
+		size = index + utf8.RuneLen(r)
+	}
+
+	return input, size
+}
+
+func isIdentifier(name string) bool {
+	_, consumed := parseIdentifier(name)
+	return consumed == len(name)
+}
+
+func isIdentifierStart(r rune) bool {
+	return r == '_' || r == '$' || unicode.IsLetter(r)
+}
+
+func isIdentifierContinue(r rune) bool {
+	return isIdentifierStart(r) || unicode.IsDigit(r)
+}
+
+func parseJSONString(input string) (string, int, error) {
+	decoder := json.NewDecoder(strings.NewReader(input))
+	var value string
+	if err := decoder.Decode(&value); err != nil {
+		return "", 0, err
+	}
+	return value, int(decoder.InputOffset()), nil
+}
+
+func parseJSONStreamStatement(value any) (statement, error) {
+	pair, ok := value.([]any)
+	if !ok || len(pair) != 2 {
+		return statement{}, errors.New("invalid JSON layout")
+	}
+
+	rawPath, ok := pair[0].([]any)
+	if !ok {
+		return statement{}, errors.New("invalid JSON layout")
+	}
+
+	path := make([]pathSegment, 0, len(rawPath))
+	for _, part := range rawPath {
+		switch typed := part.(type) {
+		case string:
+			path = append(path, pathSegment{
+				kind: segmentBracketString,
+				key:  typed,
+			})
+		case json.Number:
+			text := typed.String()
+			if text == "" {
+				return statement{}, errors.New("invalid JSON layout")
+			}
+			for _, r := range text {
+				if r < '0' || r > '9' {
+					return statement{}, errors.New("invalid JSON layout")
+				}
+			}
+			index, err := strconv.Atoi(text)
+			if err != nil {
+				return statement{}, errors.New("invalid JSON layout")
+			}
+			path = append(path, pathSegment{
+				kind:  segmentIndex,
+				index: index,
+			})
+		default:
+			return statement{}, errors.New("invalid JSON layout")
+		}
+	}
+
+	return statement{
+		path:  path,
+		value: pair[1],
+	}, nil
+}
+
+func buildFragment(path []pathSegment, value any) any {
+	if len(path) == 0 {
+		return value
+	}
+
+	result := value
+	for i := len(path) - 1; i >= 0; i-- {
+		part := path[i]
+		if part.kind == segmentIndex {
+			array := make([]any, part.index+1)
+			array[part.index] = result
+			result = array
+			continue
+		}
+
+		result = map[string]any{
+			part.key: result,
+		}
+	}
+
+	return result
+}
+
+func mergeValues(existing, incoming any) (any, error) {
+	switch current := existing.(type) {
+	case map[string]any:
+		next, ok := incoming.(map[string]any)
+		if !ok {
+			return nil, errors.New("cannot merge object with non-object")
+		}
+		for key, incomingValue := range next {
+			if existingValue, ok := current[key]; ok {
+				merged, err := mergeValues(existingValue, incomingValue)
+				if err != nil {
+					return nil, err
+				}
+				current[key] = merged
+				continue
+			}
+			current[key] = incomingValue
+		}
+		return current, nil
+	case []any:
+		next, ok := incoming.([]any)
+		if !ok {
+			return nil, errors.New("cannot merge array with non-array")
+		}
+		if len(next) > len(current) {
+			grown := make([]any, len(next))
+			copy(grown, current)
+			current = grown
+		}
+		for index, incomingValue := range next {
+			if incomingValue == nil {
+				continue
+			}
+			if current[index] == nil {
+				current[index] = incomingValue
+				continue
+			}
+			merged, err := mergeValues(current[index], incomingValue)
+			if err != nil {
+				return nil, err
+			}
+			current[index] = merged
+		}
+		return current, nil
+	default:
+		return incoming, nil
+	}
+}
+
+func maybeUnwrapJSONRoot(value any) (any, bool) {
+	object, ok := value.(map[string]any)
+	if !ok || len(object) != 1 {
+		return nil, false
+	}
+
+	root, ok := object["json"]
+	if !ok {
+		return nil, false
+	}
+
+	return root, true
+}
+
+func marshalJSON(value any) ([]byte, error) {
+	var buf bytes.Buffer
+	encoder := json.NewEncoder(&buf)
+	encoder.SetEscapeHTML(false)
+	if err := encoder.Encode(value); err != nil {
+		return nil, err
+	}
+	return bytes.TrimSuffix(buf.Bytes(), []byte("\n")), nil
+}
+
+func marshalJSONIndent(value any) ([]byte, error) {
+	var buf bytes.Buffer
+	encoder := json.NewEncoder(&buf)
+	encoder.SetEscapeHTML(false)
+	encoder.SetIndent("", "  ")
+	if err := encoder.Encode(value); err != nil {
+		return nil, err
+	}
+	return bytes.TrimSuffix(buf.Bytes(), []byte("\n")), nil
+}
+
+func newScanner(data []byte) *bufio.Scanner {
+	scanner := bufio.NewScanner(bytes.NewReader(data))
+	max := len(data) + 1
+	if max < 1024 {
+		max = 1024
+	}
+	scanner.Buffer(make([]byte, 1024), max)
+	return scanner
+}
+
+func copyPath(path []pathSegment) []pathSegment {
+	if len(path) == 0 {
+		return nil
+	}
+	out := make([]pathSegment, len(path))
+	copy(out, path)
+	return out
+}
+
+func appendPath(path []pathSegment, part pathSegment) []pathSegment {
+	next := make([]pathSegment, len(path)+1)
+	copy(next, path)
+	next[len(path)] = part
+	return next
+}
+
+func compareInts(left, right int) int {
+	switch {
+	case left < right:
+		return -1
+	case left > right:
+		return 1
+	default:
+		return 0
+	}
+}
