package main

import (
	"bufio"
	"bytes"
	"crypto/tls"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"net/http"
	neturl "net/url"
	"os"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

const helpText = `Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`

const versionText = "gron version dev\n"

type options struct {
	ungron     bool
	values     bool
	colorize   bool
	monochrome bool
	stream     bool
	insecure   bool
	jsonOutput bool
	noSort     bool
	proxy      string
	noProxy    string
	version    bool
	help       bool
}

type segmentKind int

const (
	segmentIdentifier segmentKind = iota
	segmentBracketString
	segmentIndex
)

type pathSegment struct {
	kind  segmentKind
	key   string
	index int
}

type statement struct {
	path  []pathSegment
	value any
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	opts, inputArg, parseErr := parseArgs(args)
	if parseErr != nil {
		printUsage()
		return 2
	}
	if opts.help {
		printUsage()
		return 0
	}
	if opts.version {
		_, _ = io.WriteString(os.Stdout, versionText)
		return 0
	}

	data, code, err := readInput(inputArg, opts)
	if err != nil {
		printErr(err)
		return code
	}

	if opts.ungron {
		if opts.jsonOutput {
			return runJSONUngron(data)
		}
		return runPlainUngron(data)
	}

	if opts.values {
		return runValues(data)
	}

	if opts.stream {
		return runForwardStream(data, opts)
	}

	return runForward(data, opts)
}

func parseArgs(args []string) (options, string, error) {
	var opts options

	fs := flag.NewFlagSet("gron", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = printUsage

	fs.BoolVar(&opts.help, "h", false, "")
	fs.BoolVar(&opts.help, "help", false, "")
	fs.BoolVar(&opts.ungron, "u", false, "")
	fs.BoolVar(&opts.ungron, "ungron", false, "")
	fs.BoolVar(&opts.values, "v", false, "")
	fs.BoolVar(&opts.values, "values", false, "")
	fs.BoolVar(&opts.colorize, "c", false, "")
	fs.BoolVar(&opts.colorize, "colorize", false, "")
	fs.BoolVar(&opts.monochrome, "m", false, "")
	fs.BoolVar(&opts.monochrome, "monochrome", false, "")
	fs.BoolVar(&opts.stream, "s", false, "")
	fs.BoolVar(&opts.stream, "stream", false, "")
	fs.BoolVar(&opts.insecure, "k", false, "")
	fs.BoolVar(&opts.insecure, "insecure", false, "")
	fs.StringVar(&opts.proxy, "x", "", "")
	fs.StringVar(&opts.proxy, "proxy", "", "")
	fs.StringVar(&opts.noProxy, "noproxy", "", "")
	fs.BoolVar(&opts.jsonOutput, "j", false, "")
	fs.BoolVar(&opts.jsonOutput, "json", false, "")
	fs.BoolVar(&opts.noSort, "no-sort", false, "")
	fs.BoolVar(&opts.version, "version", false, "")

	if err := fs.Parse(args); err != nil {
		return options{}, "", err
	}

	inputArg := ""
	if fs.NArg() > 0 {
		inputArg = fs.Arg(0)
	}

	return opts, inputArg, nil
}

func printUsage() {
	_, _ = io.WriteString(os.Stderr, helpText)
}

func printErr(err error) {
	_, _ = fmt.Fprintf(os.Stderr, "%v\n", err)
}

func readInput(inputArg string, opts options) ([]byte, int, error) {
	if inputArg == "" || inputArg == "-" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, 2, err
		}
		return data, 0, nil
	}

	if strings.HasPrefix(inputArg, "http://") || strings.HasPrefix(inputArg, "https://") {
		return fetchURL(inputArg, opts)
	}

	file, err := os.Open(inputArg)
	if err != nil {
		return nil, 1, err
	}
	defer file.Close()

	data, err := io.ReadAll(file)
	if err != nil {
		return nil, 2, err
	}
	return data, 0, nil
}

func fetchURL(rawURL string, opts options) ([]byte, int, error) {
	transport := http.DefaultTransport.(*http.Transport).Clone()
	if opts.insecure {
		transport.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
	}
	if opts.proxy != "" || opts.noProxy != "" {
		transport.Proxy = buildProxyFunc(opts.proxy, opts.noProxy)
	}

	client := &http.Client{Transport: transport}
	resp, err := client.Get(rawURL)
	if err != nil {
		return nil, 4, err
	}
	defer resp.Body.Close()

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, 4, err
	}
	return data, 0, nil
}

func buildProxyFunc(proxyValue, noProxyValue string) func(*http.Request) (*neturl.URL, error) {
	var noProxyHosts map[string]struct{}
	if noProxyValue != "" {
		noProxyHosts = map[string]struct{}{}
		for _, host := range strings.Split(noProxyValue, ",") {
			host = strings.TrimSpace(host)
			if host != "" {
				noProxyHosts[host] = struct{}{}
			}
		}
	}

	return func(req *http.Request) (*neturl.URL, error) {
		if len(noProxyHosts) > 0 {
			if _, ok := noProxyHosts[req.URL.Host]; ok {
				return nil, nil
			}
		}
		if proxyValue == "" {
			return http.ProxyFromEnvironment(req)
		}
		return neturl.Parse(proxyValue)
	}
}

func runForward(data []byte, opts options) int {
	value, err := decodeJSON(data)
	if err != nil {
		printErr(fmt.Errorf("failed to form statements: %w", err))
		return 3
	}

	stmts := collectStatements(value, nil)
	if !opts.noSort {
		sortStatements(stmts)
	}

	if err := writeStatements(os.Stdout, stmts, opts.jsonOutput); err != nil {
		printErr(fmt.Errorf("failed to encode JSON: %w", err))
		return 6
	}

	return 0
}

func runForwardStream(data []byte, opts options) int {
	root := statement{
		path:  nil,
		value: []any{},
	}
	if err := writeStatement(os.Stdout, root, opts.jsonOutput); err != nil {
		printErr(fmt.Errorf("failed to encode JSON: %w", err))
		return 6
	}

	scanner := newScanner(data)
	for index := 0; scanner.Scan(); index++ {
